// Assemble the triage prompt. Two passes in one call: the hard
// disqualifier gate first, then capability overlap scoring — the order
// matters, because a failed hard gate makes the score irrelevant.
//
// Everything Caravann-specific comes from the context endpoint, so
// editing the sector map in Settings changes the verdicts. Nothing about
// Caravann is hardcoded here.

const config = $('Config').first().json;
const context = $('Load triage context').first().json;
const payload = config.payload;

// Either the extracted PDF text or the raw text posted in.
const extracted = $input.first().json;
const documentText = extracted.text || payload.document_text || '';

if (!documentText.trim()) {
  throw new Error('No document text — document_url produced no extractable text and no document_text was supplied.');
}

const profile = context.org_profile || {};
const sectors = context.sector_experience || [];
const portalRules = context.portal_rules || [];

const profileBlock = [
  `Bilingual staff: ${profile.bilingual_staff ? 'yes' : 'no'}`,
  `Media production capability: ${profile.media_production_capable ? 'yes' : 'no'}`,
  `PR capability: ${profile.pr_capable ? 'yes' : 'no'}`,
  `Office locations: ${(profile.office_locations || []).join(', ') || 'none recorded'}`,
  `Consultant locations: ${(profile.consultant_locations || []).join(', ') || 'none recorded'}`,
  `Certifications: ${(profile.certifications || []).join(', ') || 'none recorded'}`,
  `Set-aside status: ${(profile.set_aside_status || []).join(', ') || 'none'}`,
  profile.notes ? `Notes: ${profile.notes}` : null,
].filter(Boolean).join('\n');

const sectorBlock = sectors.length
  ? sectors.map(s => `- ${s.sector}: ${s.years_experience ?? '?'} years, ${s.engagement_count ?? '?'} engagements${s.notes ? ` (${s.notes})` : ''}`).join('\n')
  : 'No sector experience recorded yet.';

const portalBlock = portalRules.length
  ? portalRules.map(r => `- ${r.portal_name}: ${r.rule_text}`).join('\n')
  : 'None recorded.';

const system = `You are the qualification engine for Caravann Consulting's RFP bid desk.

You read a full government solicitation and return a structured verdict. Caravann's principal reads your verdict INSTEAD OF the document, so a miss costs them either a wasted week or a lost bid. Be exact and be honest about uncertainty.

HOW TO JUDGE

1. HARD GATE FIRST. Walk every stated requirement in the solicitation. For each, decide whether Caravann meets it, using ONLY the profile below — never assume a capability that is not recorded.
   - Requirement worded as REQUIRED/MUST/SHALL and not met -> result "fail", is_required true. Any such failure forces status "no_go".
   - Requirement worded as PREFERRED/DESIRED/SHOULD and not met -> result "fail", is_required false. This LOWERS the score but never by itself forces no_go.
   - Requirement Caravann meets -> "pass". Requirement that does not apply -> "not_applicable".

2. THEN SCORE capability overlap 0-100 against Caravann's recorded sectors and capabilities. Weigh: how squarely the scope sits in a sector Caravann has real depth in, timeline feasibility, and budget versus the effort implied. A score at or above 90 means the work is squarely what Caravann already does and wins.

3. VERDICT. "go" = clears every hard gate and scores well. "no_go" = fails a required gate, or the overlap is too thin to be worth the hours. "maybe" = clears the hard gates but something real is unresolved (thin sector depth, tight timeline, budget that may not cover the effort). Use "maybe" honestly — a false "go" costs a wasted week, and a false "no_go" costs a winnable contract.

4. BUDGET. Read the not-to-exceed / contract value from the SOLICITATION TEXT ONLY. Never estimate, never infer from scope size. If the document names no figure anywhere, set budget_amount null and budget_source "none_listed". If the figure came from an attached Q&A rather than the RFP body, use "qa_document".

5. GAPS. Everything Caravann is short on for THIS solicitation, tagged by type. This is a teaming shopping list — it must be specific enough that a reader knows what a partner firm would need to bring. "Lacks behavioral health experience" is useful; "lacks experience" is not.

6. COMPLIANCE. Every rule that can disqualify a bid on a technicality: due date, question deadline, page and section limits, fonts and sizes, required sections, submission method and file-count rules, insurance, and evaluation rubric weights. Put real dates in due_at as ISO 8601. Submission mechanics matter as much as deadlines — a three-reference requirement with one upload slot belongs here.

7. QUESTIONS. Draft strategic questions for the public memo lane, and one direct request to the named contact for an incumbent or prior winning proposal in the incumbent_request lane. NEVER draft a question the solicitation already answers — check first. Keep the memo short enough to be answered inside the window.

Write verdict_why and verdict_why_not as plain prose a busy principal can scan. No hedging filler, no restating the requirement list.`;

const user = `CARAVANN ELIGIBILITY PROFILE\n${profileBlock}\n\nCARAVANN SECTOR EXPERIENCE\n${sectorBlock}\n\nKNOWN PORTAL RULES (fold any that apply into the compliance checklist)\n${portalBlock}\n\n---\n\nSOLICITATION TEXT\n\n${documentText}`;

return [{ json: { system, user, model: config.model, bid_desk_url: config.bid_desk_url, payload } }];

// Shape the model's verdict into the intake route's contract.
//
// A hard-knockout override lives on the app side, not here: this workflow
// reports what the solicitation requires and whether Caravann meets it,
// and Khaled's own knockout flags decide whether a given failure is fatal.

const prompt = $('Build triage prompt').first().json;
const payload = prompt.payload;
const response = $input.first().json;

const raw = response?.choices?.[0]?.message?.content;
if (!raw) {
  throw new Error(`OpenRouter returned no content: ${JSON.stringify(response).slice(0, 500)}`);
}

let verdict;
try {
  verdict = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (e) {
  throw new Error(`Could not parse triage JSON: ${e.message} — got: ${String(raw).slice(0, 500)}`);
}

// Caller-supplied fields win over the model's reading — if the aggregator
// email already named the agency, that beats an inference from page one.
const body = {
  external_id: payload.external_id,
  title: payload.title || verdict.title,
  client_agency: payload.client_agency || verdict.client_agency,
  project_type: verdict.project_type,
  source: payload.source || 'manual',
  source_url: payload.source_url || payload.document_url || null,
  due_at: verdict.due_at,
  question_deadline_at: verdict.question_deadline_at,
  budget_amount: verdict.budget_amount,
  budget_source: verdict.budget_source,
  status: verdict.status,
  score_percent: verdict.score_percent,
  verdict_why: verdict.verdict_why,
  verdict_why_not: verdict.verdict_why_not,
  verdict_set_at: new Date().toISOString(),
  disqualifier_checks: (verdict.disqualifier_checks || []).map(c => ({
    requirement_text: c.requirement_text,
    is_required: c.is_required,
    result: c.result,
    notes: c.notes,
  })),
  gap_items: verdict.gap_items || [],
  compliance_items: verdict.compliance_items || [],
  questions: (verdict.questions || []).map(q => ({ lane: q.lane, question_text: q.question_text })),
};

return [{ json: { body, bid_desk_url: prompt.bid_desk_url, usage: response.usage || null } }];

// Turns a Gmail message into the same payload shape the webhook accepts, so
// everything downstream of Config is identical for both entry points.
//
// Preference order for what actually gets triaged:
//   1. A linked PDF  — the solicitation itself, the only authoritative source.
//   2. A portal/bid link — likely to resolve to the solicitation.
//   3. The email body — a fallback. Aggregator summaries paraphrase, and their
//      dollar estimates are often well off the real not-to-exceed figure, so a
//      verdict built from one is weaker. Flagged so it is visible downstream.

const LINK_NOISE = /unsubscribe|list-manage|mailchimp|sendgrid|sparkpost|hubspot|googleusercontent|\.gif|\.png|\.jpg|mailto:|utm_|\/track\/|click\.|email\./i;
const PORTALish = /bid|solicit|procure|rfp|rfq|opportunit|contract|planetbids|bidnet|bonfire|periscope|demandstar|sam\.gov/i;

function urlsIn(text) {
  const found = text.match(/https?:\/\/[^\s"'<>)\]]+/g) || [];
  return found
    .map((u) => u.replace(/[.,;:]+$/, ""))
    .filter((u) => !LINK_NOISE.test(u));
}

const out = [];

for (const item of $input.all()) {
  const m = item.json;

  const subject = (m.subject || "(no subject)").trim();
  const bodyText = m.text || m.textPlain || m.snippet || "";
  const bodyHtml = m.html || m.textHtml || "";
  const haystack = `${bodyText}\n${bodyHtml}`;

  const links = urlsIn(haystack);
  const pdf = links.find((u) => /\.pdf(\?|$)/i.test(u));
  const portal = links.find((u) => PORTALish.test(u));
  const chosen = pdf || portal || null;

  // Gmail's message id is stable and unique, so re-processing the same email
  // upserts the same RFP row rather than creating a duplicate.
  const externalId = `gmail-${m.id || m.messageId || Date.now()}`;

  const payload = {
    external_id: externalId,
    source: "email",
    source_url: chosen || undefined,
    email_subject: subject,
    email_from: m.from?.value?.[0]?.address || m.From || null,
  };

  if (chosen) {
    payload.document_url = chosen;
  } else {
    payload.document_text = [
      `Subject: ${subject}`,
      "",
      bodyText || "(no plain-text body)",
      "",
      "[NOTE FOR TRIAGE: no solicitation link was found in this email, so the",
      "text above is an aggregator summary rather than the solicitation itself.",
      "Treat any budget figure as unconfirmed unless the RFP is attached, and",
      "prefer 'maybe' over a confident verdict where the summary is thin.]",
    ].join("\n");
  }

  out.push({ json: { body: payload } });
}

return out;
